/**
 * Design system of the app: Material 3 tokens built from the app icon.
 *
 * Colors come from `colors.ts` (generated by `scripts/generate-theme.mjs`);
 * everything else is defined here. Screens read the tokens for the current
 * light/dark mode through `useAppTheme()`.
 */
import { useColorScheme } from '@/hooks/use-color-scheme';

import {
  DarkColors,
  DarkCustomColors,
  LightColors,
  LightCustomColors,
  type ColorRole,
  type CustomColorName,
} from './colors';

export { IconColors, type ColorRole, type CustomColorName } from './colors';

export type ColorScheme = Record<ColorRole, string>;
export type CustomColors = Record<
  CustomColorName,
  { color: string; onColor: string; colorContainer: string; onColorContainer: string }
>;

/**
 * M3 type scale (https://m3.material.io/styles/typography/type-scale-tokens).
 * No `fontFamily`: the system font is Roboto on Android and SF on iOS, which
 * is what M3 specifies for each platform.
 */
export const Typography = {
  displayLarge: { fontSize: 57, lineHeight: 64, fontWeight: '400', letterSpacing: -0.25 },
  displayMedium: { fontSize: 45, lineHeight: 52, fontWeight: '400', letterSpacing: 0 },
  displaySmall: { fontSize: 36, lineHeight: 44, fontWeight: '400', letterSpacing: 0 },
  headlineLarge: { fontSize: 32, lineHeight: 40, fontWeight: '400', letterSpacing: 0 },
  headlineMedium: { fontSize: 28, lineHeight: 36, fontWeight: '400', letterSpacing: 0 },
  headlineSmall: { fontSize: 24, lineHeight: 32, fontWeight: '400', letterSpacing: 0 },
  titleLarge: { fontSize: 22, lineHeight: 28, fontWeight: '400', letterSpacing: 0 },
  titleMedium: { fontSize: 16, lineHeight: 24, fontWeight: '500', letterSpacing: 0.15 },
  titleSmall: { fontSize: 14, lineHeight: 20, fontWeight: '500', letterSpacing: 0.1 },
  bodyLarge: { fontSize: 16, lineHeight: 24, fontWeight: '400', letterSpacing: 0.5 },
  bodyMedium: { fontSize: 14, lineHeight: 20, fontWeight: '400', letterSpacing: 0.25 },
  bodySmall: { fontSize: 12, lineHeight: 16, fontWeight: '400', letterSpacing: 0.4 },
  labelLarge: { fontSize: 14, lineHeight: 20, fontWeight: '500', letterSpacing: 0.1 },
  labelMedium: { fontSize: 12, lineHeight: 16, fontWeight: '500', letterSpacing: 0.5 },
  labelSmall: { fontSize: 11, lineHeight: 16, fontWeight: '500', letterSpacing: 0.5 },
} as const;

export type TypographyToken = keyof typeof Typography;

/** 4dp grid; prefer the multiples of 8 for layout and 4 for fine tuning. */
export const Space = {
  none: 0,
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 24,
  xxl: 32,
  xxxl: 48,
  huge: 64,
} as const;

/**
 * M3 corner radius scale. The icon is all soft, blobby shapes and rounded
 * strokes, so components use the rounder end of what M3 allows for them
 * (see `ComponentShape`).
 */
export const Shape = {
  none: 0,
  extraSmall: 4,
  small: 8,
  medium: 12,
  large: 16,
  largeIncreased: 20,
  extraLarge: 28,
  extraLargeIncreased: 32,
  full: 9999,
} as const;

/** Corner radius per component. */
export const ComponentShape = {
  button: Shape.full,
  fab: Shape.large,
  card: Shape.largeIncreased,
  textField: Shape.medium,
  chip: Shape.small,
  dialog: Shape.extraLarge,
  bottomSheet: Shape.extraLarge,
  navigationIndicator: Shape.full,
  listItemImage: Shape.medium,
} as const;

/** Minimum touch target (dp), from M3 and the Android accessibility guidelines. */
export const MinTouchTarget = 48;

/**
 * M3 elevation levels. In M3 elevation is shown mainly by the surface tone
 * (`surface` → `surfaceContainerHighest`); a shadow is added only where the
 * element floats over content (FAB, menus, dialogs).
 */
export const Elevation = {
  level0: { dp: 0, surface: 'surface', shadow: false },
  level1: { dp: 1, surface: 'surfaceContainerLow', shadow: false },
  level2: { dp: 3, surface: 'surfaceContainer', shadow: false },
  level3: { dp: 6, surface: 'surfaceContainerHigh', shadow: true },
  level4: { dp: 8, surface: 'surfaceContainerHigh', shadow: true },
  level5: { dp: 12, surface: 'surfaceContainerHighest', shadow: true },
} as const satisfies Record<string, { dp: number; surface: ColorRole; shadow: boolean }>;

export type ElevationLevel = keyof typeof Elevation;

/** Component → elevation level, per the M3 component specs. */
export const ComponentElevation = {
  /** Filled card: no shadow, `surfaceContainer` tone (a step above `surface`). */
  card: 'level2',
  navigationBar: 'level2',
  topAppBarScrolled: 'level2',
  fab: 'level3',
  menu: 'level2',
  dialog: 'level3',
} as const satisfies Record<string, ElevationLevel>;

/**
 * `boxShadow` for an elevation level (supported on Android, iOS and web
 * since React Native 0.76); `undefined` for levels drawn by tone only.
 */
export function shadowFor(level: ElevationLevel, colors: ColorScheme) {
  const { dp, shadow } = Elevation[level];
  if (!shadow) return undefined;
  return `0px ${Math.round(dp / 2)}px ${dp * 2}px ${colors.shadow}33`;
}

export type AppTheme = {
  dark: boolean;
  colors: ColorScheme;
  custom: CustomColors;
  typography: typeof Typography;
  space: typeof Space;
  shape: typeof Shape;
  elevation: typeof Elevation;
};

export const LightTheme: AppTheme = {
  dark: false,
  colors: LightColors,
  custom: LightCustomColors,
  typography: Typography,
  space: Space,
  shape: Shape,
  elevation: Elevation,
};

export const DarkTheme: AppTheme = {
  ...LightTheme,
  dark: true,
  colors: DarkColors,
  custom: DarkCustomColors,
};

/** Tokens for the current system light/dark setting. */
export function useAppTheme(): AppTheme {
  return useColorScheme() === 'dark' ? DarkTheme : LightTheme;
}

/** M3 state layer opacities, drawn over a component in its content color. */
export const StateLayer = {
  hover: 0.08,
  focus: 0.1,
  pressed: 0.1,
  dragged: 0.16,
} as const;

/** M3 opacities for disabled components. */
export const Disabled = {
  container: 0.1,
  content: 0.38,
} as const;

/** `color` with `alpha` (0–1) for a `#RRGGBB` color. */
export function withAlpha(color: string, alpha: number) {
  return `${color}${Math.round(alpha * 255)
    .toString(16)
    .padStart(2, '0')}`;
}

/**
 * Third-party brand colors that must not follow the app theme: the Google
 * sign-in button has to follow Google's branding guidelines
 * (https://developers.google.com/identity/branding-guidelines).
 */
export const BrandColors = {
  google: {
    light: { container: '#FFFFFF', outline: '#747775', content: '#1F1F1F' },
    dark: { container: '#131314', outline: '#8E918F', content: '#E3E3E3' },
    /** Blue of the "G" mark. */
    mark: '#4285F4',
  },
} as const;

/**
 * Colors fixed by third-party content: the ExerciseDB GIFs have a white
 * background, so their frame stays white in dark mode too.
 */
export const MediaColors = {
  exerciseGif: '#FFFFFF',
} as const;
